import collections, hashlib, json, os, pathlib, statistics, subprocess, threading, time
ROOT=pathlib.Path.cwd(); OUT=ROOT/'target/issue784/performance'; OUT.mkdir(exist_ok=True)
protocol=json.loads((ROOT/'docs/experiments/treeaci-784-hints-protocol.json').read_text())
bins={'baseline':ROOT/'target/issue784/baseline-build/release/examples/convergence_g0','candidate':ROOT/'target/issue784/candidate-g0'}
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
git=lambda *a:subprocess.check_output(['git',*a],text=True).strip()
manifest={'protocol':protocol,'baseline_commit':git('-C','../tensor4all-rs-784-current-baseline','rev-parse','HEAD'),'candidate_commit':git('rev-parse','HEAD'),'binaries':{k:{'path':str(v.relative_to(ROOT)),'sha256':sha(v)} for k,v in bins.items()},'lock_sha256':sha(ROOT/'Cargo.lock'),'harness_sha256':sha(ROOT/'crates/tensor4all-treeaci/examples/convergence_g0.rs'),'fixture_sha256':sha(ROOT/'crates/tensor4all-treeaci/tests/support/g0.rs'),'recorder_source':pathlib.Path(__file__).read_text(),'observations':[],'warmups':[]}
assert manifest['baseline_commit']==protocol['baseline_commit']
assert git('status','--porcelain')==''
for path in ['crates/tensor4all-treeaci/examples/convergence_g0.rs','crates/tensor4all-treeaci/tests/support/g0.rs','Cargo.lock']:
 assert sha(ROOT/path)==sha(ROOT.parent/'tensor4all-rs-784-current-baseline'/path)
env=os.environ.copy();env.update(protocol['thread_environment'])

def snapshot():
 cpus={}
 for l in pathlib.Path('/proc/stat').read_text().splitlines():
  p=l.split()
  if p and p[0].startswith('cpu'):cpus[p[0]]=list(map(int,p[1:9]))
 vm=dict(l.split() for l in pathlib.Path('/proc/vmstat').read_text().splitlines())
 mem=dict(l.split(':',1) for l in pathlib.Path('/proc/meminfo').read_text().splitlines())
 return {'time':time.monotonic(),'cpu':cpus,'pswpout':int(vm['pswpout']),'available_bytes':int(mem['MemAvailable'].split()[0])*1024}
noise=[];stop=threading.Event()
def monitor():
 while not stop.is_set():noise.append(snapshot());stop.wait(0.5)
thread=threading.Thread(target=monitor);thread.start()

def arm(label,case,name):
 assert git('rev-parse','HEAD')==manifest['candidate_commit'] and git('status','--porcelain')==''
 subprocess.run(['taskset','-c','14','python3','-c','import time\nt=time.monotonic()\nwhile time.monotonic()-t < 1.0: pass'],check=True)
 prefix=OUT/name
 with prefix.with_suffix('.stdout').open('w') as stdout, prefix.with_suffix('.stderr').open('w') as stderr:
  try:r=subprocess.run(['taskset','-c','14',str(bins[label]),*map(str,case)],env=env,stdout=stdout,stderr=stderr,timeout=600);status=r.returncode
  except subprocess.TimeoutExpired:status='timeout'
 lines=prefix.with_suffix('.stdout').read_text().splitlines()
 result=json.loads(lines[-1]) if lines else None
 record={'arm':label,'case':case,'status':status,'result':result,'stdout':prefix.with_suffix('.stdout').read_text(),'stderr':prefix.with_suffix('.stderr').read_text()}
 print(name,status, None if result is None else (result['seconds'],result['termination'],len(result['ranks'])),flush=True)
 return record
try:
 for label in bins:manifest['warmups'].append(arm(label,[5,'nblock',0.1],'warmup-'+label))
 for i,case in enumerate(protocol['cases']):
  for repetition in range(protocol['repetitions']):
   labels=['baseline','candidate'] if (i+repetition)%2==0 else ['candidate','baseline']
   for label in labels:manifest['observations'].append(arm(label,case,f'case{i}-rep{repetition}-{label}'))
finally:
 stop.set();thread.join();noise.append(snapshot());manifest['noise_samples']=noise
 a,b=noise[0],noise[-1]
 rates={}
 for key,initial in a['cpu'].items():
  delta=[v-u for u,v in zip(initial,b['cpu'][key])];total=sum(delta)
  rates[key]={'busy':(total-delta[3]-delta[4])/total if total else 0,'steal':delta[7]/total if total else 0}
 manifest['noise_summary']={'swapout_pages':b['pswpout']-a['pswpout'],'global_steal_fraction':rates['cpu']['steal'],'mean_cpu15_busy_fraction':rates['cpu15']['busy'],'mean_other_busy_cores':sum(v['busy'] for k,v in rates.items() if k not in ['cpu','cpu14','cpu15']),'available_memory_min_bytes':min(n['available_bytes'] for n in noise)}
 gates=protocol['noise_gates'];n=manifest['noise_summary']
 valid=n['swapout_pages']<=gates['swapout_pages_delta_max'] and n['global_steal_fraction']<=gates['global_steal_fraction_max'] and n['mean_cpu15_busy_fraction']<=gates['mean_cpu15_busy_fraction_max'] and n['mean_other_busy_cores']<=gates['mean_other_busy_cores_max'] and n['available_memory_min_bytes']>=gates['available_memory_min_bytes']
 valid=valid and all(o['status']==0 and o['result'] for o in manifest['observations']+manifest['warmups']) and len(manifest['observations'])==36
 (OUT/'results.json').write_text(json.dumps(manifest,indent=2)+'\n')
 rows=[]
 for case in protocol['cases']:
  medians={label:statistics.median([o['result']['seconds'] for o in manifest['observations'] if o['arm']==label and o['case']==case and o['result']]) for label in bins}
  rows.append({'case':case,**medians,'ratio':medians['candidate']/medians['baseline'],'per_case_gate':medians['candidate']<=1.2*medians['baseline']+0.05})
 manifest['comparison']=rows
 ratio=sum(r['candidate'] for r in rows)/sum(r['baseline'] for r in rows)
 manifest['aggregate_ratio']=ratio
 convergence=all(o['result'] and o['result']['termination']=='Converged' for o in manifest['observations'] if o['arm']=='candidate')
 manifest['all_candidate_converged']=convergence
 manifest['verdict']='INCONCLUSIVE' if not valid else ('PASS' if convergence and ratio<=1.1 and all(r['per_case_gate'] for r in rows) else 'FAIL')
 manifest['limitations']='Three repetitions; descriptive medians without confidence intervals. Quality is checked on 1093 points per arm, not exhaustively. WSL host frequency and scheduling are not fully observable. Does not isolate historical #896 differences.'
 (OUT/'results.json').write_text(json.dumps(manifest,indent=2)+'\n')
 print(manifest['verdict'],ratio,manifest['noise_summary'],flush=True)
